code.python:
def removeAdjacentDuplicates(s: str) -> str:
    stack = []
    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)
    return ''.join(stack)

code.cpp:
string removeAdjacentDuplicates(string s) {
    string stack;
    for (char value : s) {
        if (!stack.empty() && stack.back() == value) stack.pop_back();
        else stack.push_back(value);
    }
    return stack;
}

code.java:
public String removeAdjacentDuplicates(String s) {
    StringBuilder stack = new StringBuilder();
    for (char value : s.toCharArray()) {
        int last = stack.length() - 1;
        if (last >= 0 && stack.charAt(last) == value) stack.deleteCharAt(last);
        else stack.append(value);
    }
    return stack.toString();
}

code.javascript:
function removeAdjacentDuplicates(s) {
  const stack = [];
  for (const char of s) {
    if (stack.at(-1) === char) stack.pop();
    else stack.push(char);
  }
  return stack.join('');
}

