code.cpp:
vector<int> implementStackUsingArray(vector<int>& items) {
    vector<int> stack;
    for (int item : items) {
        if (!stack.empty() && stack.back() == item) stack.pop_back();
        else stack.push_back(item);
    }
    return stack;
}

code.java:
public int[] implementStackUsingArray(int[] items) {
    Deque<Integer> stack = new ArrayDeque<>();
    for (int item : items) {
        if (!stack.isEmpty() && stack.peek() == item) stack.pop();
        else stack.push(item);
    }
    return stack.stream().mapToInt(Integer::intValue).toArray();
}

