def largestRectangleInHistogram(items):
    stack = []
    for item in items:
        if stack and stack[-1] == item:
            stack.pop()
        else:
            stack.append(item)
    return stack

code.cpp:
vector<int> largestRectangleInHistogram(vector<int>& items) {
    vector<int> stack;
    for (int item : items) {
        if (!stack.empty() && stack.back() == item) stack.pop_back();
        else stack.push_back(item);
    }
    return stack;
}

code.java:
public int[] largestRectangleInHistogram(int[] items) {
    Deque<Integer> stack = new ArrayDeque<>();
    for (int item : items) {
        if (!stack.isEmpty() && stack.peek() == item) stack.pop();
        else stack.push(item);
    }
    return stack.stream().mapToInt(Integer::intValue).toArray();
}

code.javascript:
function largestRectangleInHistogram(items) {
  const stack = [];
  for (const item of items) {
    if (stack.at(-1) === item) stack.pop();
    else stack.push(item);
  }
  return stack;
}

