code.python:
def houseRobber(n):
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + (dp[i - 2] if i > 1 else 0)
    return dp[n]

code.cpp:
int houseRobber(int n) {
    vector<int> dp(n + 1);
    dp[0] = 1;
    for (int i = 1; i <= n; i++) dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);
    return dp[n];
}

code.java:
public int houseRobber(int n) {
    int[] dp = new int[n + 1];
    dp[0] = 1;
    for (int i = 1; i <= n; i++) dp[i] = dp[i - 1] + (i > 1 ? dp[i - 2] : 0);
    return dp[n];
}

